/** A 로컬 윤곽(반시계): 이뿌리 평지 → 비탈 → 곧은 면 */
export function sawWheelOutline241(): V2[] {
  const pts: V2[] = [];
  const pol = (r: number, a: number): V2 => [Math.cos(a * D) * r, Math.sin(a * D) * r];
  for (let j = 0; j < K.N; j++) {
    const a = K.ALPHA0 + 20 * j;
    for (let i = 0; i < 4; i++) pts.push(pol(K.RR, a + (K.LAND * i) / 3));
    for (let k = 1; k <= 10; k++) {
      const u = k / 10;
      pts.push(pol(K.RR + 0.14 * u, a + K.LAND + u * 13 - (k === 10 ? 0.0001 : 0)));
    }
  }
  return pts;
}

export function sawWheel241(): THREE.Group {
  const g = new THREE.Group();
  const outline = sawWheelOutline241();
  const shape = new THREE.Shape();
  outline.forEach(([x, y], i) => (i === 0 ? shape.moveTo(x, y) : shape.lineTo(x, y)));
  shape.closePath();
  const geo = extrude(shape, K.T, 0, 8);
  geo.translate(0, 0, K.T / 2);
  g.add(mesh(geo, brass()));
  const hubGeo = new THREE.CylinderGeometry(0.16, 0.16, 0.1, 48);
  hubGeo.rotateX(Math.PI / 2);
  const hub = mesh(hubGeo, darkSteel());
  hub.position.z = 0.04;
  const ringGeo = new THREE.RingGeometry(0.1, 0.13, 48);
  const ring = mesh(ringGeo, steel());
  ring.position.z = 0.091;
  const band = mesh(new THREE.BoxGeometry(0.55, 0.05, 0.006), paint(0xf2b619));
  band.position.set(0.45, 0, 0.083);
  g.add(hub, ring, band);
  g.userData.outline = outline;
  return g;
}

function plate(outline: V2[], holeR: number, mat: THREE.Material): THREE.Mesh {
  const shape = new THREE.Shape();
  outline.forEach(([x, y], i) => (i === 0 ? shape.moveTo(x, y) : shape.lineTo(x, y)));
  shape.closePath();
  const hole = new THREE.Path();
  hole.absarc(0, 0, holeR, 0, TAU, true);
  shape.holes.push(hole);
  const geo = extrude(shape, K.T, 0, 24);
  geo.translate(0, 0, K.T / 2);
  return mesh(geo, mat);
}

export function finger241(): THREE.Group {
  const g = new THREE.Group();
  g.add(plate(FINGER_OUTLINE, 0.04, paint(0xd8362f)));
  g.userData.outline = FINGER_OUTLINE;
  return g;
}

export function click241(): THREE.Group {
  const g = new THREE.Group();
  g.add(plate(CLICK_OUTLINE, 0.03, steel({ roughness: 0.22 })));
  g.userData.outline = CLICK_OUTLINE;
  return g;
}

const SAW = sawWheelOutline241();

function segDist(px: number, py: number, ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax;
  const dy = by - ay;
  const L = dx * dx + dy * dy || 1e-12;
  const t = Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / L));
  return Math.hypot(px - ax - t * dx, py - ay - t * dy);
}

/** A 를 θA(라디안)만큼 돌렸을 때 점 (x, y)(세계)에서 A 윤곽까지 최소 거리 */
function distToA(x: number, y: number, thetaA: number): number {
  const c = Math.cos(thetaA);
  const s = Math.sin(thetaA);
  const px = x - K.C[0];
  const py = y - K.C[1];
  // 점을 A 로컬로(−θA)
  const lx = c * px + s * py;
  const ly = -s * px + c * py;
  let best = Infinity;
  const n = SAW.length;
  for (let i = 0; i < n; i++) {
    const a = SAW[i]!;
    const b = SAW[(i + 1) % n]!;
    const d = segDist(lx, ly, a[0], a[1], b[0], b[1]);
    if (d < best) best = d;
  }
  return best;
}

function gammaFor(thetaA: number): number {
  const g0 = K.GAMMA0 * D;
  // A 는 20° 주기 — (−20°, 0] 로 줄여 쓴다
  const per = 20 * D;
  const th = thetaA - Math.floor(thetaA / per) * per - per;
  const nose = (g: number): number =>
    distToA(K.PC[0] + K.LC * Math.cos(g), K.PC[1] + K.LC * Math.sin(g), th) - K.RN;
  let hi = g0 + 0.3;
  let lo = hi;
  let found = false;
  for (let g = g0 + 0.3; g > g0 - 0.5; g -= 0.002) {
    if (nose(g) <= 0) {
      lo = g;
      found = true;
      break;
    }
    hi = g;
  }
  if (!found) return g0;
  for (let i = 0; i < 30; i++) {
    const mid = (lo + hi) / 2;
    if (nose(mid) <= 0) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

export function state241(t: number): { thetaS: number; thetaA: number; gamma: number; pushing: boolean } {
  const thE = K.TH_E * D;
  const thetaS = thE + K.OMEGA * t;
  const k = Math.floor((thetaS - thE) / TAU);
  const u = thetaS - thE - TAU * k;
  const pushing = u <= K.SPAN * D;
  let thetaA: number;
  if (pushing) {
    const [sx, sy] = K.S;
    const th = thE + u;
    const px = sx + K.R1 * Math.cos(th);
    const py = sy + K.R1 * Math.sin(th);
    const dx = px - K.C[0];
    const dy = py - K.C[1];
    const rho = Math.hypot(dx, dy);
    let beta = Math.atan2(dy, dx);
    if (beta < 0) beta += TAU;
    let phi: number;
    if (rho * rho - K.RPIN * K.RPIN <= K.RT * K.RT) phi = beta - Math.asin(K.RPIN / rho);
    else phi = beta - Math.acos((rho * rho + K.RT * K.RT - K.RPIN * K.RPIN) / (2 * rho * K.RT));
    thetaA = -k * 20 * D + (phi - K.PHI_E * D);
  } else thetaA = -(k + 1) * 20 * D;
  return { thetaS, thetaA, gamma: gammaFor(thetaA), pushing };
}
